// The Bitcoin whitepaper as a poster (18.5 by 24.5 inches), rendered from the maintainer's PDF at 167 dpi and scaled
// to 2060x2728 (111 dpi, ample for the stone's face on screen), its greys quantised to the sixteen steps the page's own
// boards are drawn in, kept as lossless WebP, and set into the library's monolith (scene-hub.js). One picture, a data
// URL, so the portable page needs no request for it; a hosted page serves it as a file under art/ (`--image-assets`).
(() => {
  "use strict";
  const BL = window.BL = window.BL || {};
  BL.whitepaperPoster = { poster: "data:image/webp;base64," };
})();
